import React from 'react';

const Chat = ({ chatId }) => {
  // Assuming the chat URL can be constructed using the chatId
  const chatSrc = `https://www.youtube.com/live_chat?v=${chatId}&embed_domain=yourdomain.com`;

  return (
    <div className="chat-container">
      <iframe
        width="100%"
        height="500"
        src={chatSrc}
        frameBorder="0"
        allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"
        allowFullScreen
        title="Chat"
      ></iframe>
    </div>
  );
};

export default Chat;
